  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#e08a72");
  let grassColor = "#8aa46c";
  let sunColor = "#ffa24a";

  // Sky
  brush.fill(grassColor, 1.0);
  brush.beginShape(0.4);
  brush.vertex(0, 400);  // bottom left
  brush.vertex(200, 200);  // middle
  brush.vertex(400, 400);  // top right
  brush.endShape(true);

  // Green hills
  brush.fill(grassColor, 1.0);
  brush.beginShape(0.5);
  brush.vertex(200, 0);  // bottom middle
  brush.vertex(200, 200);  // middle
  brush.vertex(400, 200);  // top right
  brush.endShape(true);

  // Sun
  brush.fill(sunColor, 0.5);
  brush.beginShape(0.6);
  brush.vertex(200, 200);  // middle
  brush.vertex(400, 400);  // top right
  brush.vertex(200, 100);  // bottom middle
  brush.endShape(true);

  // Explain where the other graphics are
  drawText("Over a green hill");
} 

