function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Sky
  brush.fill('#4f8b4f', 100); //蔚蓝天空
  brush.fillBleed(0.3);
  brush.beginShape(0.5); // 创建一个较为柔和的边界
  brush.vertex(200, 100); // 创建天空的边界
  brush.vertex(400, 200); // 创建一个圆
  brush.vertex(300, 200);
  brush.vertex(200, 400);
  brush.endShape(true);
  // 边界与300px的距离
  brush.vertex(200, 100); 
  brush.vertex(300, 400);
  brush.vertex(500, 200);
  brush.vertex(100, 200);
  brush.vertex(100, 100);
  // hills
  brush.fill('#3b6e3b', 50); // 绿色的山地
  brush.fillBleed(0.3);
  brush.fillTexture(0.8, 0.6); // 添加一些纹理效果
  brush.beginShape(0.5); // 使用半径进行创建
  brush.vertex(200, 200); // 创建一个边界
  brush.vertex(300, 400); // 点击选择角度
  brush.vertex(500, 300); 
  brush.vertex(400, 100); 
  brush.vertex(200, 100); // 点击确认边界
  brush.endShape(true);
  // ground
  brush.fill('#4e9c6f', 100); // 绿色的草坪
  brush.fillBleed(0.3);
  brush.fillTexture(0.5, 0.3); // 添加一些杂乱的效果
  brush.beginShape(0.5); 
  brush.vertex(200, 100); // 创建一个边界
  brush.vertex(300, 300);
  brush.vertex(500, 300); 
  brush.vertex(300, 200);
  brush.vertex(200, 200); // 创建一个边界
  brush.vertex(100, 300); 
  brush.endShape(true); 
}
