  brush.fill("#11ff49", 80);       // Sky
  brush.beginShape(0.9);          // Sharp edge
  brush.vertex(200, 200);        // Right point
  brush.vertex(220, 200);       // Right side
  brush.vertex(200, 200);       // Left point
  brush.vertex(220, 100);       // Left side
  brush.endShape(true);
  // Green hills
  brush.fill("#66bb4b", 100);
  brush.beginShape(0.8);         // Sharp edge
  brush.vertex(200, 200);      // Bottom right point
  brush.vertex(240, 200);     // Bottom right side
  brush.vertex(200, 100);     // Bottom left point
  brush.vertex(240, 100);    // Bottom left side
  brush.endShape(true);
  // Palms
  brush.fill("#008e7b", 100);
  brush.beginShape(0.8);       // Sharp edge
  brush.vertex(240, 200);    // Bottom right point
  brush.vertex(240, 200);   // Bottom right side
  brush.vertex(240, 100);   // Bottom left point
  brush.vertex(220, 200);   // Bottom left side
  brush.endShape(true);
  // Horizons
  brush.fill("#228b22", 50);
  brush.beginShape(0.9);      // Sharp edge
  brush.vertex(240, 100);   // Right bottom point
  brush.vertex(220, 100);  // Right bottom side
  brush.vertex(240, 200);  // Right top point
  brush.vertex(220, 200);  // Right top side
  brush.endShape(true);
}
